            <Button type="button" variant={noEmail?"default":"outline"} onClick={()=>setNoEmail(v=>!v)} className={"shrink-0 "+(noEmail?"bg-destructive text-destructive-foreground hover:bg-destructive/90":"border-destructive/50 text-destructive hover:bg-destructive/10")}>{noEmail?"N/A":"Sem e-mail"}</Button>
