function StockDialog({open,close,onSave,initial}:{open:boolean;close:()=>void;onSave:(s:Stock)=>void;initial?:Stock|null}){const isPart=(initial?.itemType??"part")==="part";const qualities=["Incell","Soft OLED","OLED","Genuína","Original","Primeira linha","Original usada","Retirada usada","Retirada original","Outro"];const partTypes=["Tela","Bateria","Conector de carga","Câmera","Flex","Alto-falante","Microfone","Carcaça","Tampa traseira","Botão","Placa","Chip / CI","Lente de câmera","Outro"];const brands=["Apple","Motorola","Samsung","Xiaomi","Realme","Huawei","LG","Asus","Lenovo","Outras"];const storeCategories=["Capas","Películas","Carregadores","Cabos","Fontes","Fones","Suportes","Acessórios","Outros"];return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>{initial?"Editar item":"Novo item de estoque"}</DialogTitle><DialogDescription>Cadastre peças técnicas e produtos da loja com informações padronizadas. Use “Outros” para informar livremente.</DialogDescription></DialogHeader><form className="grid gap-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const itemType=String(f.get("itemType"))==="store"?"store":"part";const customPart=String(f.get("customPart")||"").trim();const customBrand=String(f.get("customBrand")||"").trim();const customQuality=String(f.get("customQuality")||"").trim();const partType=String(f.get("partType")||"");const brand=String(f.get("brand")||"");const quality=String(f.get("quality")||"");const finalPart=partType==="Outro"?customPart:partType;const finalBrand=brand==="Outras"?customBrand:brand;const finalQuality=quality==="Outro"?customQuality:quality;onSave({id:initial?.id??crypto.randomUUID(),sku:String(f.get("sku")),name:String(f.get("name")),itemType,category:String(f.get("category")),partType:finalPart,brand:finalBrand,model:String(f.get("model")||""),quality:finalQuality,supplier:String(f.get("supplier")),location:String(f.get("location")),quantity:Number(f.get("quantity")),minimum:Number(f.get("minimum")),cost:Number(f.get("cost")),price:Number(f.get("price")),movements:initial?.movements??[]})}}><div className="grid gap-4 sm:grid-cols-2"><Field label="Tipo de item"><select name="itemType" defaultValue={initial?.itemType??"part"} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="part">Peça técnica</option><option value="store">Produto da loja</option></select></Field><Field label="Categoria"><select name="category" defaultValue={initial?.category??""} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione</option>{isPart?partTypes.map(x=><option key={x} value={x}>{x}</option>):storeCategories.map(x=><option key={x} value={x}>{x}</option>)}</select></Field>{isPart&&<><Field label="Tipo de peça"><select name="partType" defaultValue={initial?.partType??"Tela"} className="h-10 rounded-md border bg-background px-3 text-sm">{partTypes.map(x=><option key={x} value={x}>{x}</option>)}</select></Field><Field label="Marca"><select name="brand" defaultValue={initial?.brand??""} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione</option>{brands.map(x=><option key={x} value={x}>{x}</option>)}</select></Field><Field label="Modelo / referência"><Input name="model" defaultValue={initial?.model} placeholder="Ex.: iPhone 14 Pro Max"/></Field><Field label="Qualidade da peça"><select name="quality" defaultValue={initial?.quality??""} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione</option>{qualities.map(x=><option key={x} value={x}>{x}</option>)}</select></Field></>}<Field label={isPart?"Nome da peça":"Nome do produto"}><Input name="name" required defaultValue={initial?.name} placeholder={isPart?"Ex.: Tela iPhone 14":"Ex.: Película 3D"}/></Field><Field label="SKU / código"><Input name="sku" defaultValue={initial?.sku} placeholder="Opcional"/></Field><Field label="Fornecedor"><Input name="supplier" defaultValue={initial?.supplier}/></Field><Field label="Localização"><Input name="location" defaultValue={initial?.location} placeholder="A-01"/></Field><Field label="Saldo"><Input name="quantity" type="number" min="0" defaultValue={initial?.quantity??0} required/></Field><Field label="Estoque mínimo"><Input name="minimum" type="number" min="0" defaultValue={initial?.minimum??1} required/></Field><Field label="Custo unitário"><Input name="cost" type="number" min="0" step="0.01" defaultValue={initial?.cost??0} required/></Field><Field label="Preço de venda"><Input name="price" type="number" min="0" step="0.01" defaultValue={initial?.price??0} required/></Field></div><FormActions close={close} label={initial?"Salvar alterações":"Cadastrar item"}/></form></DialogContent></Dialog>}
function MovementDialog({open,item,close,onSave}:{open:boolean;item:Stock|null;close:()=>void;onSave:(id:string,n:number,t:string,note:string)=>void}){const [type,setType]=useState("entry");if(!item)return null;return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent><DialogHeader><DialogTitle>Movimentar estoque</DialogTitle><DialogDescription>{item.name} • saldo atual: {item.quantity}</DialogDescription></DialogHeader><form className="grid gap-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),n=Number(f.get("quantity"));if(type==="exit"&&n>item.quantity){alert("A saída não pode ser maior que o saldo disponível.");return}onSave(item.id,n,type,String(f.get("note")))}}><div className="grid grid-cols-2 gap-2"><Button type="button" variant={type==="entry"?"default":"outline"} onClick={()=>setType("entry")}><Plus/>Entrada</Button><Button type="button" variant={type==="exit"?"default":"outline"} onClick={()=>setType("exit")}><Minus/>Saída</Button></div><Field label="Quantidade"><Input name="quantity" type="number" min="1" max={type==="exit"?item.quantity:undefined} required/></Field><Field label="Motivo / referência"><Input name="note" required placeholder="Compra, ajuste, perda…"/></Field><div className="rounded-md bg-muted p-3"><p className="text-xs font-bold">Últimas movimentações</p>{item.movements.slice(0,3).map((m,i)=><p key={i} className="mt-2 text-xs text-muted-foreground">{m.date} • {m.type} • {m.quantity} un. • {m.note}</p>)}</div><FormActions close={close} label="Registrar movimentação"/></form></DialogContent></Dialog>}
function CustomerPicker({customers,onSelect,onCreate}:{customers:Customer[];onSelect:(id:string)=>void;onCreate:()=>void}){
  const [open,setOpen]=useState(false),[term,setTerm]=useState(""),[chosen,setChosen]=useState<Customer|null>(null);
  const pickerRef=useRef<HTMLDivElement>(null);
  const found=customers.filter(c=>`${c.name} ${c.document}`.toLowerCase().includes(term.toLowerCase()));
  useEffect(()=>{
    if(!open)return;
    const handlePointerDown=(event:PointerEvent)=>{
      if(pickerRef.current && !pickerRef.current.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown",handlePointerDown);
    return()=>document.removeEventListener("pointerdown",handlePointerDown);
  },[open]);
  return <div ref={pickerRef} className="relative">
    <div className="mb-1.5 flex items-center justify-between gap-2">
      <span className="text-sm font-semibold">Cliente</span>
      <Button type="button" variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={onCreate}><Plus className="size-3.5"/>Cadastrar cliente</Button>
    </div>
    <Button type="button" variant="outline" className="h-auto min-h-10 w-full justify-between text-left font-normal" onClick={()=>setOpen(v=>!v)}>
      <span>{chosen?<><b>{chosen.name}</b><span className="ml-2 text-muted-foreground">{chosen.document}</span></>:"Selecione pelo nome ou documento"}</span><ChevronDown className="size-4 shrink-0"/>
    </Button>
    {open&&<div className="absolute z-20 mt-1 w-full rounded-md border bg-popover p-2 shadow-lg">
      <div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input autoFocus value={term} onChange={e=>setTerm(e.target.value)} placeholder="Pesquisar nome, CPF ou CNPJ" className="pl-9"/></div>
      <div className="mt-2 max-h-48 overflow-y-auto">{found.map(c=><Button key={c.id} type="button" variant="ghost" className="h-auto w-full justify-start py-2 text-left" onClick={()=>{setChosen(c);onSelect(c.id);setOpen(false)}}><span><b className="block">{c.name}</b><small className="text-muted-foreground">{c.document}</small></span></Button>)}{!found.length&&<div className="p-3 text-sm text-muted-foreground"><p>Nenhum cliente encontrado.</p><Button type="button" variant="link" className="mt-1 h-auto p-0" onClick={onCreate}><Plus className="size-4"/>Cadastrar agora</Button></div>}</div>
    </div>}
  </div>
}
function OsEntryExtras({category}:{category:string}){const [photos,setPhotos]=useState<string[]>([]),[approved,setApproved]=useState(false);const checklist=checklistByCategory[category]??[];return <div className="grid gap-4 rounded-lg border bg-muted/20 p-4"><div><h3 className="font-bold">Checklist de entrada{category?" — "+category:""}</h3><p className="mt-1 text-xs text-muted-foreground">{category?"Registre o estado de cada item na recepção. Fica salvo na ordem e sai impresso.":"Escolha o tipo de equipamento para ver o checklist adequado."}</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{checklist.map(item=><label key={item} className="flex items-center justify-between gap-2 rounded-md border bg-background p-2 text-xs"><span className="font-medium">{item}</span><select name={"check::"+item} defaultValue="Não testado" className="h-8 rounded border bg-background px-2 text-xs"><option>OK</option><option>Com defeito</option><option>Não testado</option><option>Não se aplica</option></select></label>)}</div></div><div><h3 className="font-bold">Fotos do aparelho</h3><p className="mt-1 text-xs text-muted-foreground">Frente, traseira e danos existentes. As imagens ficam apenas na sessão enquanto o banco de fotos não estiver implantado.</p><input className="mt-3 block w-full text-sm" type="file" accept="image/*" multiple onChange={e=>{const files=Array.from(e.target.files??[]).slice(0,6);Promise.all(files.map(file=>new Promise<string>(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.readAsDataURL(file)}))).then(setPhotos)}}/>{photos.length>0&&<div className="mt-3 grid grid-cols-3 gap-2">{photos.map((src,i)=><img key={i} src={src} alt={"Foto "+(i+1)+" do aparelho"} className="aspect-square rounded-md border object-cover"/> )}</div>}</div><div className="flex flex-col gap-3 rounded-md border bg-background p-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-bold">Orçamento e aprovação</h3><p className="text-xs text-muted-foreground">Fluxo futuro: enviar orçamento por link e registrar aprovação do cliente.</p></div><Button type="button" variant={approved?"default":"outline"} onClick={()=>setApproved(v=>!v)}>{approved?"✓ Aprovado (simulação)":"Simular aprovação"}</Button></div></div>}
function WorkbenchView({orders,onSection,onView}:{orders:Order[];onSection:(s:Section)=>void;onView:(o:Order)=>void}){const columns=["Aberta","Em processo","Finalizada"] as const;const active=orders.filter(o=>!["Finalizada","Cancelada"].includes(o.stage));return <div className="space-y-5"><div className="rounded-xl border bg-card p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-bold">Bancada técnica</h2><p className="text-xs text-muted-foreground">Visão operacional das ordens. O técnico pode consultar os dados da OS sem alterar o cadastro por esta tela.</p></div><Button variant="outline" onClick={()=>onSection("Ordens de serviço")}>Ver todas as OS</Button></div></div><div className="grid gap-4 lg:grid-cols-3">{columns.map(column=>{const items=orders.filter(o=>o.stage===column);return <section key={column} className="min-h-[320px] rounded-xl border bg-muted/20 p-3"><div className="mb-3 flex items-center justify-between"><h3 className="font-bold">{column}</h3><span className="rounded-full bg-background px-2 py-1 text-xs font-bold">{items.length}</span></div><div className="grid gap-3">{items.map(o=><article key={o.id} className="rounded-lg border bg-card p-4 shadow-sm"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-primary">{o.id}</p><h4 className="mt-1 font-bold">{o.device}</h4><p className="text-xs text-muted-foreground">{o.client}</p></div><span className="text-xs font-semibold">{money(o.total)}</span></div><div className="mt-3 flex flex-wrap gap-1 text-[10px]"><span className="rounded bg-muted px-2 py-1">{o.issue||"Sem descrição"}</span><span className="rounded bg-muted px-2 py-1">Técnico: {o.tech}</span></div><div className="mt-3 flex justify-end"><Button variant="outline" size="sm" onClick={()=>onView(o)}><Eye/>Visualizar OS</Button></div></article>)}{!items.length&&<p className="rounded-md border border-dashed p-6 text-center text-xs text-muted-foreground">Nenhum aparelho nesta etapa.</p>}</div></section>})}</div><div className="grid gap-4 sm:grid-cols-3"><Stat label="Aparelhos na bancada" value={String(active.length)}/><Stat label="Aguardando atendimento" value={String(orders.filter(o=>o.stage==="Aberta").length)}/><Stat label="Em processo" value={String(orders.filter(o=>o.stage==="Em processo").length)}/></div></div>}
function ReportsView({orders,stock,sales,financeEntries,warranties,company}:{orders:Order[];stock:Stock[];sales:Sale[];financeEntries:FinanceEntry[];warranties:Warranty[];company:CompanySettings}){const [range,setRange]=useState<DateRange>({from:shiftDateKey(0),to:shiftDateKey(0)});const [reportType,setReportType]=useState<"complete"|"assistance"|"store">("complete");const visibleOrders=orders.filter(o=>inDateRange(o.createdAt,range));const visibleWarranties=warranties.filter(w=>inDateRange(w.createdAt,range));const visibleSales=sales.filter(s=>inDateRange(s.sold_at,range));const visibleFinance=financeEntries.filter(e=>inDateRange(e.entry_date,range));const assistanceSales=visibleSales.filter(s=>s.department==="assistance"||s.department==="parts");const storeSales=visibleSales.filter(s=>s.department==="store");const visibleAssistanceOrders=reportType==="store"?[]:visibleOrders;const shownAssistanceSales=reportType==="store"?[]:assistanceSales;const shownStoreSales=reportType==="assistance"?[]:storeSales;const revenueAssistance=assistanceSales.reduce((a,s)=>a+Number(s.total),0);const revenueStore=storeSales.reduce((a,s)=>a+Number(s.total),0);const expenses=visibleFinance.filter(e=>e.entry_type==="expense").reduce((a,e)=>a+Number(e.amount),0);const period=range.from&&range.to?new Date(range.from+"T12:00:00").toLocaleDateString("pt-BR")+" a "+new Date(range.to+"T12:00:00").toLocaleDateString("pt-BR"):"todos os períodos";const makeReport=()=>{const rows:string[]=[];if(reportType!=="store"){rows.push("<h2>Assistência técnica</h2><table><tbody><tr><th>Ordens de serviço registradas</th><td>"+visibleAssistanceOrders.length+"</td></tr><tr><th>OS abertas</th><td>"+visibleOrders.filter(o=>o.stage==="Aberta").length+"</td></tr><tr><th>OS em processo</th><td>"+visibleOrders.filter(o=>o.stage==="Em processo").length+"</td></tr><tr><th>OS finalizadas</th><td>"+visibleOrders.filter(o=>o.stage==="Finalizada").length+"</td></tr><tr><th>Vendas registradas da assistência</th><td>"+money(revenueAssistance)+"</td></tr><tr><th>Quantidade de vendas da assistência</th><td>"+assistanceSales.length+"</td></tr></tbody></table>")}if(reportType!=="assistance"){rows.push("<h2>Produtos da loja</h2><table><tbody><tr><th>Vendas registradas de produtos da loja</th><td>"+money(revenueStore)+"</td></tr><tr><th>Quantidade de vendas da loja</th><td>"+storeSales.length+"</td></tr></tbody></table>")}rows.push("<h2>Resumo financeiro do período</h2><table><tbody><tr><th>Receitas registradas em vendas</th><td>"+money(visibleSales.reduce((a,s)=>a+Number(s.total),0))+"</td></tr><tr><th>Despesas registradas</th><td>"+money(expenses)+"</td></tr>"+(reportType!=="store"?"<tr><th>Garantias emitidas</th><td>"+visibleWarranties.length+"</td></tr>":"")+"</tbody></table>");const title=reportType==="assistance"?"Relatório de assistência técnica":reportType==="store"?"Relatório de produtos da loja":"Relatório gerencial completo";const html="<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><title>"+escapeHtml(title)+"</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#172033;font-size:12px;margin:0}.head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;border-bottom:3px solid #2563eb;padding-bottom:14px;margin-bottom:20px}.brand{font-size:22px;font-weight:800}.muted{color:#667085;font-size:11px;margin-top:4px}.badge{border:1px solid #2563eb;color:#2563eb;padding:6px 9px;font-weight:700}h1{font-size:19px;margin:0 0 4px}h2{font-size:14px;margin:24px 0 8px;color:#1d4ed8}table{width:100%;border-collapse:collapse;margin-bottom:18px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e5e7eb}td{text-align:right;font-weight:700}tr:nth-child(odd){background:#f8fafc}.print{margin-bottom:18px;padding:8px 12px}@media print{.print{display:none}}</style></head><body><button class='print' onclick='window.print()'>Imprimir / Salvar como PDF</button><div class='head'><div><div class='brand'>"+escapeHtml(company.name||"Sua empresa")+"</div><div class='muted'>"+escapeHtml(company.document||"")+(company.phone?" • "+escapeHtml(company.phone):"")+"</div><div class='muted'>"+escapeHtml(company.address||company.email||"")+"</div></div><div class='badge'>"+escapeHtml(title)+"</div></div><h1>"+escapeHtml(title)+"</h1><p class='muted'>Período consultado: "+escapeHtml(period)+"</p>"+rows.join("")+"<p class='muted'>Relatório gerado em "+new Date().toLocaleString("pt-BR")+". Os valores de vendas refletem os registros realizados no sistema no período selecionado.</p></body></html>";const popup=window.open("about:blank","_blank");if(!popup){alert("O navegador bloqueou a janela do relatório. Permita pop-ups para imprimir ou salvar em PDF.");return}popup.document.write(html);popup.document.close();popup.focus();window.setTimeout(()=>popup.print(),400)};return <div className="space-y-5"><div><h1 className="font-display text-2xl font-extrabold">Relatórios</h1><p className="mt-1 text-sm text-muted-foreground">Escolha o período e gere um relatório para imprimir ou salvar em PDF.</p></div><DateRangeFilter value={range} onChange={setRange} label="Período do relatório"/><section className="rounded-xl border bg-card p-5 shadow-card"><div className="grid gap-4 md:grid-cols-[1fr_2fr] md:items-end"><Field label="Tipo de relatório"><select value={reportType} onChange={e=>setReportType(e.target.value as typeof reportType)} className="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="complete">Relatório gerencial completo</option><option value="assistance">Somente assistência técnica</option><option value="store">Somente produtos da loja</option></select></Field><div className="flex flex-wrap gap-2"><Button onClick={makeReport}><FileDown/>Gerar PDF / Imprimir</Button><Button variant="outline" onClick={makeReport}><Printer/>Visualizar relatório</Button></div></div><p className="mt-3 text-xs text-muted-foreground">Na janela de impressão, selecione “Salvar como PDF” para guardar o arquivo. Não há relatório de venda de peças: elas são controladas por entrada e consumo na assistência técnica.</p></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{reportType!=="store"&&<><Stat label="OS no período" value={String(visibleAssistanceOrders.length)}/><Stat label="Vendas da assistência" value={money(revenueAssistance)}/></>}{reportType!=="assistance"&&<><Stat label="Vendas de produtos da loja" value={money(revenueStore)}/><Stat label="Vendas da loja (quantidade)" value={String(storeSales.length)}/></>}</div>{reportType!=="store"&&<section className="rounded-xl border bg-card p-5 shadow-card"><h2 className="font-bold">Assistência técnica</h2><div className="mt-4 space-y-3 text-sm"><div className="flex justify-between border-b pb-3"><span>Ordens registradas no período</span><b>{visibleOrders.length}</b></div><div className="flex justify-between border-b pb-3"><span>OS abertas</span><b>{visibleOrders.filter(o=>o.stage==="Aberta").length}</b></div><div className="flex justify-between border-b pb-3"><span>OS em processo</span><b>{visibleOrders.filter(o=>o.stage==="Em processo").length}</b></div><div className="flex justify-between border-b pb-3"><span>OS finalizadas</span><b>{visibleOrders.filter(o=>o.stage==="Finalizada").length}</b></div><div className="flex justify-between"><span>Vendas registradas da assistência</span><b>{money(revenueAssistance)}</b></div></div></section>}{reportType!=="assistance"&&<section className="rounded-xl border bg-card p-5 shadow-card"><h2 className="font-bold">Produtos da loja</h2><div className="mt-4 space-y-3 text-sm"><div className="flex justify-between border-b pb-3"><span>Quantidade de vendas</span><b>{storeSales.length}</b></div><div className="flex justify-between"><span>Valor total vendido</span><b>{money(revenueStore)}</b></div></div></section>}<section className="rounded-xl border bg-card p-5 shadow-card"><h2 className="font-bold">Resumo financeiro do período</h2><p className="mt-1 text-xs text-muted-foreground">Valores de vendas registradas no sistema, separados por área.</p><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><div className="rounded-lg bg-blue-50 p-4 dark:bg-blue-950/40"><p className="text-xs text-muted-foreground">Assistência técnica</p><p className="mt-1 text-xl font-bold">{money(revenueAssistance)}</p></div><div className="rounded-lg bg-violet-50 p-4 dark:bg-violet-950/40"><p className="text-xs text-muted-foreground">Produtos da loja</p><p className="mt-1 text-xl font-bold">{money(revenueStore)}</p></div><div className="rounded-lg bg-muted p-4"><p className="text-xs text-muted-foreground">Despesas registradas</p><p className="mt-1 text-xl font-bold">{money(expenses)}</p></div></div></section></div>}

function OrderDialog({open,customers,stock,close,onSave,onCreateCustomer}:{open:boolean;customers:Customer[];stock:Stock[];close:()=>void;onSave:(o:Order,p:{id:string;quantity:number}|null)=>void;onCreateCustomer:(c:Customer&{address?:string;notes?:string})=>Promise<Customer|null>}){
  const [customerId,setCustomerId]=useState(""),[partId,setPartId]=useState(""),[category,setCategory]=useState(""),[brand,setBrand]=useState(""),[model,setModel]=useState(""),[customBrand,setCustomBrand]=useState(""),[customModel,setCustomModel]=useState(""),[serialNA,setSerialNA]=useState(false),[quickCustomerOpen,setQuickCustomerOpen]=useState(false);
  const brands=[...Object.keys(deviceCatalog[category]??{}),"Outros"];
  const models=brand&&brand!=="Outros"?[...(deviceCatalog[category]?.[brand]??[]),"Outros"]:[];
  useEffect(()=>{setBrand("");setModel("");setCustomBrand("");setCustomModel("")},[category]);
  useEffect(()=>{setModel("");setCustomModel("")},[brand]);
  const finalBrand=brand==="Outros"?customBrand.trim():brand;
  const finalModel=model==="Outros"?customModel.trim():model;
  return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-3xl">
    <DialogHeader><DialogTitle>Nova ordem de serviço</DialogTitle><DialogDescription>Cadastre o aparelho com listas padronizadas e use “Outros” quando a marca ou modelo não estiver na lista.</DialogDescription></DialogHeader>
    <form className="grid gap-4" onSubmit={e=>{
      e.preventDefault();
      const f=new FormData(e.currentTarget),c=customers.find(x=>x.id===customerId);
      if(!c){alert("Selecione um cliente cadastrado.");return}
      if(!category||!finalBrand||!finalModel){alert("Selecione o equipamento e informe a marca e o modelo.");return}
      const part=stock.find(x=>x.id===partId),qty=Number(f.get("partQuantity")||0);
      if(part&&qty>part.quantity){alert("A quantidade da peça é maior que o saldo disponível.");return}
      const parts=part&&qty?[{name:part.name,quantity:qty,price:part.price}]:[];
      const total=Number(f.get("serviceValue")||0)+parts.reduce((a,p)=>a+p.quantity*p.price,0);
      onSave({id:"OS-PENDENTE",customerId:c.id,client:c.name,document:c.document,device:`${finalBrand} ${finalModel}`,deviceCategory:category,brand:finalBrand,model:finalModel,serial:serialNA?"N/A":String(f.get("serial")||""),issue:String(f.get("issue")||""),apparentIssue:String(f.get("apparentIssue")||""),terms:String(f.get("terms")||""),stage:"Aberta",tech:"Não atribuído",total,phone:c.phone,checklist:Array.from(f.entries()).filter(([k])=>String(k).startsWith("check::")).map(([k,v])=>({item:String(k).slice(7),result:String(v)})),due:String(f.get("due")||"A definir"),tone:"slate",parts},part&&qty?{id:part.id,quantity:qty}:null)
    }}>
      <CustomerPicker customers={customers} onSelect={setCustomerId} onCreate={()=>setQuickCustomerOpen(true)}/>
      <CustomerDialog open={quickCustomerOpen} close={()=>setQuickCustomerOpen(false)} onSave={async c=>{const created=await onCreateCustomer(c);if(created){setCustomerId(created.id);setQuickCustomerOpen(false);}}}/>
      <div className="grid gap-4 sm:grid-cols-3">
        <Field label="Tipo de equipamento"><select name="category" value={category} onChange={e=>setCategory(e.target.value)} required className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione</option>{Object.keys(deviceCatalog).map(x=><option key={x} value={x}>{x}</option>)}</select></Field>
        <Field label="Marca"><select name="brand" value={brand} onChange={e=>setBrand(e.target.value)} disabled={!category} required className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">{category?"Selecione a marca":"Escolha o tipo primeiro"}</option>{brands.map(x=><option key={x} value={x}>{x}</option>)}</select></Field>
        {brand==="Outros"?<Field label="Digite a marca"><Input value={customBrand} onChange={e=>setCustomBrand(e.target.value)} placeholder="Ex.: Infinix, Oppo, TCL…"/></Field>:<Field label="Modelo"><select name="model" value={model} onChange={e=>setModel(e.target.value)} disabled={!brand} required={!!brand} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">{brand?"Selecione o modelo":"Escolha a marca primeiro"}</option>{models.map(x=><option key={x} value={x}>{x}</option>)}</select></Field>}
        {brand==="Outros"&&<Field label="Digite o modelo"><Input value={customModel} onChange={e=>setCustomModel(e.target.value)} placeholder="Modelo do aparelho"/></Field>}
        {brand!=="Outros"&&model==="Outros"&&<Field label="Digite o modelo"><Input value={customModel} onChange={e=>setCustomModel(e.target.value)} placeholder="Digite o modelo que não está na lista"/></Field>}
        <Field label="Número de série / IMEI"><div className="flex gap-2"><Input name="serial" placeholder={serialNA?"N/A":"IMEI ou número de série"} disabled={serialNA} className="flex-1"/><Button type="button" variant={serialNA?"default":"outline"} onClick={()=>setSerialNA(v=>!v)} className={"shrink-0 "+(serialNA?"bg-destructive text-destructive-foreground hover:bg-destructive/90":"border-destructive/50 text-destructive hover:bg-destructive/10")}>{serialNA?"N/A":"Sem IMEI"}</Button></div></Field>
      </div>
      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="Defeito relatado pelo cliente"><Textarea name="issue" required placeholder="O que o cliente informou ao deixar o aparelho"/></Field>
        <Field label="Defeito aparente / constatado"><Textarea name="apparentIssue" placeholder="Sinais, danos e sintomas observados na recepção"/></Field>
      </div>
      <Field label="Termos da ordem de serviço"><Textarea name="terms" placeholder="Deixe em branco por enquanto ou registre os termos que você definir para sua segurança."/></Field><OsEntryExtras category={category}/>
      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="Peça do estoque (opcional)"><select name="part" value={partId} onChange={e=>setPartId(e.target.value)} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Nenhuma peça</option>{stock.filter(s=>s.itemType==="part" && ["Tela","Bateria","Conector de carga","Câmera","Flex","Alto-falante","Microfone","Carcaça","Tampa traseira","Botão","Placa","Chip / CI","Lente de câmera","Outro"].includes(s.category)).map(s=><option key={s.id} value={s.id} disabled={s.quantity<=0}>{s.name}{s.category?" ("+s.category+")":""} — saldo {s.quantity}{s.quantity<=0?" (sem estoque)":""}</option>)}</select></Field>
        <Field label="Quantidade da peça"><Input name="partQuantity" type="number" min="1" defaultValue="1" disabled={!partId} title={!partId?"Selecione uma peça primeiro":undefined}/></Field>
        <Field label="Valor do serviço"><Input name="serviceValue" type="number" min="0" step="0.01" defaultValue="0"/></Field>
        <Field label="Previsão"><Input name="due" type="date"/></Field>
      </div>
      <FormActions close={close} label="Criar ordem"/>
    </form>
  </DialogContent></Dialog>
}
function EditOrderDialog({open,order,close,onSave}:{open:boolean;order:Order|null;close:()=>void;onSave:(o:Order)=>void}){if(!order)return null;return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Editar ordem {order.id}</DialogTitle><DialogDescription>Atualize os dados da ordem, aparelho, diagnóstico, valores e andamento.</DialogDescription></DialogHeader><form className="grid gap-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const total=Number(f.get("total")||0);onSave({...order,deviceCategory:String(f.get("category")||order.deviceCategory||"Equipamento"),brand:String(f.get("brand")||order.brand||""),model:String(f.get("model")||order.model||""),device:[String(f.get("brand")||order.brand||""),String(f.get("model")||order.model||"")].filter(Boolean).join(" "),serial:String(f.get("serial")||""),issue:String(f.get("issue")||""),apparentIssue:String(f.get("apparentIssue")||""),terms:String(f.get("terms")||""),stage:String(f.get("stage")||order.stage),total,due:String(f.get("due")||order.due)})}}><div className="grid gap-4 sm:grid-cols-3"><Field label="Tipo de equipamento"><Input name="category" defaultValue={order.deviceCategory}/></Field><Field label="Marca"><Input name="brand" defaultValue={order.brand}/></Field><Field label="Modelo"><Input name="model" defaultValue={order.model}/></Field></div><Field label="IMEI / número de série"><Input name="serial" defaultValue={order.serial}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Defeito relatado pelo cliente"><Textarea name="issue" defaultValue={order.issue}/></Field><Field label="Defeito aparente / constatado"><Textarea name="apparentIssue" defaultValue={order.apparentIssue}/></Field></div><Field label="Termos da ordem de serviço"><Textarea name="terms" defaultValue={order.terms}/></Field><div className="grid gap-4 sm:grid-cols-3"><Field label="Valor total da ordem"><Input name="total" type="number" min="0" step="0.01" defaultValue={order.total}/></Field><Field label="Situação"><select name="stage" defaultValue={order.stage} className="h-10 rounded-md border bg-background px-3 text-sm">{["Aberta","Em processo","Finalizada","Cancelada"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Previsão"><Input name="due" type="date" defaultValue={order.due==="A definir"?"":order.due.split("/").reverse().join("-")}/></Field></div><FormActions close={close} label="Salvar alterações"/></form></DialogContent></Dialog>}
function WarrantyDialog({open,orders=[],close,onSave,initial}:{open:boolean;orders?:Order[];close:()=>void;onSave:(w:Warranty)=>void;initial?:Warranty|null}){return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent><DialogHeader><DialogTitle>Emitir garantia</DialogTitle><DialogDescription>Crie o certificado a partir de uma ordem de serviço.</DialogDescription></DialogHeader><form className="grid gap-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),o=orders.find(x=>x.id===f.get("order"));if(!o)return;const days=Number(f.get("days"));onSave({id:initial?.id??`GAR-${crypto.randomUUID().slice(0,6).toUpperCase()}`,dbId:initial?.dbId,orderId:initial?.orderId??o.id,customer:initial?.customer??o.client,device:initial?.device??o.device,starts:initial?.starts??today(),expires:initial?.expires??addDays(days),coverage:String(f.get("coverage")),status:String(f.get("status")||initial?.status||"Ativa")})}}><Field label="Ordem de serviço"><select name="order" defaultValue={initial?.orderId} disabled={!!initial} required className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione a ordem</option>{orders.map(o=><option key={o.id} value={o.id}>{o.id} — {o.client} — {o.device}</option>)}</select></Field><Field label="Prazo de garantia"><select name="days" defaultValue="30" disabled={!!initial} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="30">30 dias</option><option value="90">90 dias</option><option value="180">180 dias</option><option value="365">1 ano</option></select></Field><Field label="Cobertura"><Textarea name="coverage" defaultValue={initial?.coverage} required placeholder="Serviços e peças cobertos"/></Field><Field label="Condições e exclusões"><Textarea name="terms" placeholder="Mau uso, líquidos, danos físicos…"/></Field>{initial&&<Field label="Status"><select name="status" defaultValue={initial.status} className="h-10 rounded-md border bg-background px-3 text-sm"><option>Ativa</option><option>Expirada</option><option>Cancelada</option></select></Field>}<FormActions close={close} label={initial?"Salvar alterações":"Emitir garantia"}/></form></DialogContent></Dialog>}
function OrderDocumentDialog({open,order,close,company,onPrinted}:{open:boolean;order:Order|null;close:()=>void;company:CompanySettings;onPrinted?:(o:Order)=>void}){if(!order)return null;const body=`<h1>Ordem de serviço ${escapeHtml(order.id)}</h1><div class="muted">Emitida em ${today()}</div><h2>Cliente</h2><div class="grid"><div><b>Nome</b><br>${escapeHtml(order.client)}</div><div><b>Documento</b><br>${escapeHtml(order.document)}</div></div><h2>Equipamento</h2><div class="grid"><div><b>Equipamento</b><br>${escapeHtml(order.device)}</div><div><b>Série / IMEI</b><br>${escapeHtml(order.serial||"Não informado")}</div></div><h2>Defeito relatado pelo cliente</h2><div class="box">${escapeHtml(order.issue)}</div><h2>Defeito aparente / constatado</h2><div class="box">${escapeHtml(order.apparentIssue||"Não informado")}</div><h2>Termos da ordem de serviço</h2><div class="box">${escapeHtml(order.terms||"Não informado")}</div>${order.checklist?.length?`<h2>Checklist de entrada</h2>${order.checklist.map(c=>`<div class="row"><span>${escapeHtml(c.item)}</span><b>${escapeHtml(c.result)}</b></div>`).join("")}`:""}<h2>Itens e valores</h2>${order.parts.map(p=>`<div class="row"><span>${p.quantity}x ${escapeHtml(p.name)}</span><b>${money(p.quantity*p.price)}</b></div>`).join("")}<div class="row total"><span>Total da ordem</span><span>${money(order.total)}</span></div><h2>Situação</h2><div class="box">${escapeHtml(order.stage)} • Previsão: ${escapeHtml(order.due)}</div>`;return <DocumentDialog open={open} close={close} title={`Ordem ${order.id}`} subtitle={`${order.client} • ${order.device}`} onPrint={()=>{printDocument(`Ordem ${order.id}`,body,company);onPrinted?.(order)}}><div className="grid gap-4 sm:grid-cols-2"><DocItem label="Cliente" value={order.client}/><DocItem label="Documento" value={order.document}/><DocItem label="Equipamento" value={order.device}/><DocItem label="Série / IMEI" value={order.serial||"Não informado"}/></div><div className="rounded-md bg-muted p-4"><p className="text-xs font-bold text-muted-foreground">DEFEITO RELATADO</p><p className="mt-1 text-sm">{order.issue}</p></div><div className="flex justify-between border-t pt-4 font-bold"><span>Total</span><span>{money(order.total)}</span></div></DocumentDialog>}
function WarrantyDocumentDialog({open,warranty,close,company}:{open:boolean;warranty:Warranty|null;close:()=>void;company:CompanySettings}){if(!warranty)return null;const body=`<h1>Certificado de garantia</h1><div class="muted">Código de autenticidade: ${escapeHtml(warranty.id)}</div><h2>Referência</h2><div class="grid"><div><b>Ordem</b><br>${escapeHtml(warranty.orderId)}</div><div><b>Cliente</b><br>${escapeHtml(warranty.customer)}</div><div><b>Equipamento</b><br>${escapeHtml(warranty.device)}</div><div><b>Validade</b><br>${escapeHtml(warranty.starts)} a ${escapeHtml(warranty.expires)}</div></div><h2>Cobertura</h2><div class="box">${escapeHtml(warranty.coverage)}</div><h2>Condições gerais</h2><div class="box">A garantia cobre exclusivamente os serviços e peças descritos neste certificado. Danos por mau uso, líquidos, quedas, violação ou intervenção de terceiros não estão cobertos.</div>`;return <DocumentDialog open={open} close={close} title="Certificado de garantia" subtitle={`${warranty.id} • ${warranty.orderId}`} onPrint={()=>printDocument(`Garantia ${warranty.id}`,body,company)}><div className="grid gap-4 sm:grid-cols-2"><DocItem label="Cliente" value={warranty.customer}/><DocItem label="Equipamento" value={warranty.device}/><DocItem label="Início" value={warranty.starts}/><DocItem label="Validade" value={warranty.expires}/></div><div className="rounded-md bg-muted p-4"><p className="text-xs font-bold text-muted-foreground">COBERTURA</p><p className="mt-1 text-sm">{warranty.coverage}</p></div></DocumentDialog>}
function DocumentDialog({open,close,title,subtitle,onPrint,children}:{open:boolean;close:()=>void;title:string;subtitle:string;onPrint:()=>void;children:React.ReactNode}){return <Dialog open={open} onOpenChange={v=>!v&&close()}><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{subtitle}</DialogDescription></DialogHeader><div className="grid gap-4">{children}<div className="flex flex-col-reverse gap-2 border-t pt-4 sm:flex-row sm:justify-end"><Button variant="outline" onClick={close}>Fechar</Button><Button onClick={onPrint}><Printer/>{title.toLowerCase().startsWith("ordem")?"Emitir / Imprimir ordem":"Imprimir / Salvar PDF"}</Button></div></div></DialogContent></Dialog>}
function DocItem({label,value}:{label:string;value:string}){return <div><p className="text-xs font-bold text-muted-foreground">{label.toUpperCase()}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>}